W,H=11,9
g=[[0]*W for _ in range(H)]
row=6
src=[1,2,1,8,1,1,1,8,1,2,1]
g[row]=src[:]
h={2:4,8:3}
for c,v in enumerate(src):
    if v!=1:
        for k in range(1,h[v]):
            g[row-k][c]=1
        g[row-h[v]+1][c]=v  # top cell gets marker color
for r in g: print(r)

g=[[0]*W for _ in range(H)]
g[row]=src[:]
for c,v in enumerate(src):
    if v!=1:
        h={2:4,8:3}[v]
        g[row-h][c]=v
        for k in range(1,h):
            g[row-k][c]=1
for r in g: print(r)
